import java.security.Security
import org.bouncycastle.jce.provider.BouncyCastleProvider

fun encrypt(data: ByteArray): ByteArray {
    Security.addProvider(BouncyCastleProvider()) // bad: expensive, recreated per call
    return data
}

import java.security.Security
import org.bouncycastle.jce.provider.BouncyCastleProvider

class CryptoService {
    companion object {
        init {
            Security.addProvider(BouncyCastleProvider()) // ok: registered once
        }
    }
    fun encrypt(data: ByteArray) = data
}
